-- GAME04 development only. Additive wrapper: never replace G2 growth/state functions.
-- Results are generated by the authenticated server; this RPC is service-role-only.
create or replace function public.game04_commit_gacha(
 p_user_id uuid,p_expected_version bigint,p_state jsonb,p_before_diamonds integer,
 p_diamond_cost integer,p_cash_delta bigint,p_ticket_id text,p_ticket_cost integer,
 p_request_id uuid,p_receipt jsonb
) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare u public.users%rowtype; prior jsonb; saved public.game04_player_state%rowtype;
 r jsonb:=p_receipt->'gachaReceipt'; fp jsonb; category text; payment text; action text;
 draw_count integer; cost integer; gain integer; expected_cost integer; expected_gain integer;
 point_category text; old_points bigint; new_points bigint; point_delta integer;
 ticket_quantity integer; expected_ticket text; settlement_day text;
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 -- Bind a request ID to its original operation, and replay before any debit or date check.
 select q.result into prior from public.game04_requests q where q.user_id=p_user_id and q.request_id=p_request_id;
 if found then
  if prior#>>'{receipt,gachaFingerprint}' is null or prior#>>'{receipt,gachaFingerprint}' is distinct from p_receipt->>'gachaFingerprint' then
   raise exception 'GACHA_REQUEST_MISMATCH';
  end if;
  return prior;
 end if;
 if p_request_id is null or p_state->>'userId' is distinct from p_user_id::text
  or jsonb_typeof(r) is distinct from 'object'
  or jsonb_typeof(p_receipt->'gachaFingerprint') is distinct from 'string'
  or length(p_receipt->>'gachaFingerprint') not between 2 and 1000
  or r->>'requestId' is distinct from p_request_id::text
  or r->>'masterVersion' is distinct from 'game04-g3-formal-20260925'
  or p_receipt#>>'{gameplayMeasurement,contractVersion}' is distinct from 'game04-gameplay-v1' then
  raise exception 'INVALID_GACHA_RECEIPT';
 end if;
 fp:=(p_receipt->>'gachaFingerprint')::jsonb;
 category:=r->>'category'; payment:=r->>'payment'; action:=p_receipt#>>'{gameplayMeasurement,action}';
 if not coalesce(category in ('normal','character','skill','equipment'),false)
  or not coalesce(payment in ('cash','free','gems','ticket','points'),false)
  or not coalesce(action in ('gacha_draw','gacha_exchange'),false)
  or not coalesce(r->>'count' ~ '^(1|10)$',false)
  or not coalesce(r->>'cost' ~ '^[0-9]+$',false)
  or not coalesce(r->>'pointGain' ~ '^[0-9]+$',false)
  or not coalesce(r->>'pointsAfter' ~ '^[0-9]+$',false)
  or jsonb_typeof(r->'results') is distinct from 'array'
  or jsonb_typeof(fp) is distinct from 'object'
  or fp->>'action' is distinct from action or fp->>'category' is distinct from category
  or fp->>'payment' is distinct from payment or fp->>'count' is distinct from r->>'count' then
  raise exception 'INVALID_GACHA_RECEIPT';
 end if;
 draw_count:=(r->>'count')::integer; cost:=(r->>'cost')::integer; gain:=(r->>'pointGain')::integer;
 if jsonb_array_length(r->'results')<>draw_count then raise exception 'INVALID_GACHA_RECEIPT'; end if;
 if exists(select 1 from jsonb_array_elements(r->'results') v where
  not coalesce(v->>'kind' in ('character','skill','equipment'),false)
  or not coalesce(v->>'rarity' in ('N','R','SR','SSR'),false)
  or coalesce(length(v->>'id'),0)=0
  or (category<>'normal' and (v->>'kind' is distinct from category or v->>'rarity'='N'))
  or (action='gacha_exchange' and (v->>'rarity' is distinct from 'SSR' or v->>'id' is distinct from fp->>'masterId'))
 ) then raise exception 'INVALID_GACHA_RESULT'; end if;
 expected_ticket:=case category when 'character' then 'SPECIAL_TICKET_CHARACTER' when 'skill' then 'SPECIAL_TICKET_SKILL' when 'equipment' then 'SPECIAL_TICKET_EQUIPMENT' end;
 if action='gacha_exchange' then
  if category='normal' or payment<>'points' or draw_count<>1 then raise exception 'INVALID_GACHA_PAYMENT'; end if;
  expected_cost:=case category when 'character' then 200 else 100 end; expected_gain:=0;
 elsif category='normal' then
  if payment not in ('cash','free') or (payment='free' and draw_count<>10) then raise exception 'INVALID_GACHA_PAYMENT'; end if;
  expected_cost:=case payment when 'cash' then 1000*draw_count else 0 end; expected_gain:=0;
 else
  if payment not in ('gems','ticket') or (payment='ticket' and draw_count<>1) then raise exception 'INVALID_GACHA_PAYMENT'; end if;
  expected_cost:=case payment when 'ticket' then 1 else draw_count*(case category when 'equipment' then 200 else 300 end) end;
  expected_gain:=draw_count;
 end if;
 if cost<>expected_cost or gain<>expected_gain
  or p_diamond_cost is distinct from case when payment='gems' then cost else 0 end
  or p_cash_delta is distinct from case when payment='cash' then -cost else 0 end
  or p_ticket_cost is distinct from case when payment='ticket' then 1 else 0 end
  or p_ticket_id is distinct from case when payment='ticket' then expected_ticket else null end
  or p_before_diamonds is null
  or (p_state->>'diamonds')::integer is distinct from p_before_diamonds-p_diamond_cost then
  raise exception 'INVALID_GACHA_PAYMENT';
 end if;
 select * into saved from public.game04_player_state where user_id=p_user_id for update;
 if not found then raise exception 'STATE_NOT_INITIALIZED'; end if;
 if saved.version is distinct from p_expected_version then raise exception 'STATE_CONFLICT' using errcode='40001'; end if;
 for point_category in select unnest(array['character','skill','equipment']) loop
  old_points:=coalesce((saved.state#>>array['gachaPoints',point_category])::bigint,0);
  new_points:=coalesce((p_state#>>array['gachaPoints',point_category])::bigint,0);
  point_delta:=case when category=point_category then case when action='gacha_exchange' then -cost else gain end else 0 end;
  if old_points<0 or new_points<0 or new_points<>old_points+point_delta then raise exception 'INVALID_GACHA_POINTS'; end if;
 end loop;
 if (r->>'pointsAfter')::bigint is distinct from case when category='normal' then 0 else coalesce((p_state#>>array['gachaPoints',category])::bigint,0) end then raise exception 'INVALID_GACHA_POINTS'; end if;
 settlement_day:=(clock_timestamp() at time zone 'Asia/Tokyo')::date::text;
 if payment='free' then
  if p_state->>'dailyNormalGachaDate' is distinct from settlement_day then raise exception 'GACHA_DAY_CHANGED' using errcode='40001'; end if;
  if saved.state->>'dailyNormalGachaDate'=settlement_day then raise exception 'GACHA_FREE_ALREADY_USED'; end if;
 elsif p_state->>'dailyNormalGachaDate' is distinct from saved.state->>'dailyNormalGachaDate' then raise exception 'INVALID_GACHA_DAY';
 end if;
 -- questTicketGrants is a cumulative G2 supply ledger; only user_items is spendable.
 if p_ticket_cost>0 then
  select quantity into ticket_quantity from public.user_items where user_id=p_user_id and item_id=p_ticket_id for update;
  if not found or ticket_quantity<p_ticket_cost then raise exception 'INSUFFICIENT_RESOURCE'; end if;
  update public.user_items set quantity=quantity-p_ticket_cost,updated_at=now() where user_id=p_user_id and item_id=p_ticket_id;
 end if;
 if p_diamond_cost>0 then
  -- Preserve G2 paid-lot expiration trigger before the authoritative comparison.
  update public.users set neon_diamonds=neon_diamonds where id=p_user_id returning * into u;
  if u.neon_diamonds<>p_before_diamonds then raise exception 'STATE_CONFLICT' using errcode='40001'; end if;
  if u.neon_diamonds<p_diamond_cost then raise exception 'INSUFFICIENT_RESOURCE'; end if;
  update public.users set neon_diamonds=neon_diamonds-p_diamond_cost where id=p_user_id;
 end if;
 -- All debits, acquisitions, missions, backgrounds, points and receipt commit or roll back together.
 return public.game04_commit_growth_state(p_user_id,p_expected_version,p_state,p_cash_delta,0,p_request_id,p_receipt=>p_receipt);
end $$;
revoke all on function public.game04_commit_gacha(uuid,bigint,jsonb,integer,integer,bigint,text,integer,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.game04_commit_gacha(uuid,bigint,jsonb,integer,integer,bigint,text,integer,uuid,jsonb) to service_role;
